65	// ── Audio ──────────────────────────────────────────────────────────────────
66	export function playSuccessSound() {
67	  try {
68	    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
69	    const ctx = new Ctx();
70	    const osc = ctx.createOscillator();
71	    const gain = ctx.createGain();
72	    osc.connect(gain);
73	    gain.connect(ctx.destination);
74	    osc.frequency.value = 800;
75	    osc.type = "sine";
76	    gain.gain.value = 0.1;
77	    osc.start();
78	    osc.stop(ctx.currentTime + 0.15);
79	  } catch { /* ignore */ }
80	}
81	
82	export function playErrorSound() {
83	  try {
84	    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
85	    const ctx = new Ctx();
86	    const osc = ctx.createOscillator();
87	    const gain = ctx.createGain();
88	    osc.connect(gain);
89	    gain.connect(ctx.destination);
90	    osc.frequency.setValueAtTime(300, ctx.currentTime);
91	    osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
92	    osc.type = "square";
93	    gain.gain.value = 0.1;
94	    osc.start();
95	    osc.stop(ctx.currentTime + 0.3);
96	  } catch { /* ignore */ }
97	}
98	
99	export function playWarningSound() {
100	  try {
101	    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
102	    const ctx = new Ctx();
103	    const osc = ctx.createOscillator();
104	    const gain = ctx.createGain();
105	    osc.connect(gain);
106	    gain.connect(ctx.destination);
107	    osc.frequency.value = 500;
108	    osc.type = "triangle";
109	    gain.gain.value = 0.1;
110	    osc.start();
111	    osc.stop(ctx.currentTime + 0.25);
112	  } catch { /* ignore */ }
113	}
