354	// ── Hook ───────────────────────────────────────────────────────────────────
355	export type ScanMode = "bluetooth" | "camera";
356	
357	export interface UseEtiquetaScannerOptions {
358	  enabled: boolean;
359	  onScan: (payload: ScannedPayload, raw: string) => void | Promise<void>;
360	  onInvalid?: (raw: string) => void;
361	  /**
362	   * Chamado quando o cooldown anti-repetição barrou uma leitura idêntica.
363	   * Útil pra mostrar feedback "caixa já lida" sem deixar o som tocar 60x/s.
364	   */
365	  onDuplicate?: (raw: string) => void;
366	  cameraElementId?: string;
367	  initialMode?: ScanMode;
368	}
369	
370	/**
371	 * Detecta se uma mensagem de erro da RPC bipar_etiqueta indica duplicata
372	 * — etiqueta já foi bipada NESSA ETAPA específica (separação, conferência,
373	 * entrada, saída).
374	 */
375	/**
376	 * Calcula o incremento de uma bip baseado na unidade do PEDIDO e no tipo de
377	 * embalagem da ETIQUETA.
378	 *
379	 * Regra universal:
380	 *   se pedido.unidade_medida ≈ etiqueta.tipo_embalagem  → bip soma +1
381	 *   senao                                                → bip soma +quantidade_interna
382	 *
383	 * Exemplos:
384	 *   pedido "5 caixas" + etiqueta tipo=caixa, qty=12  → +1  (1/5 caixas)
385	 *   pedido "60 un" + mesma etiqueta                  → +12 (12/60 unidades)
386	 *   pedido "10 kg" + etiqueta tipo=saco, qty=5kg     → +5  (5/10 kg)
387	 *   pedido "2 sacos" + mesma etiqueta                → +1  (1/2 sacos)
388	 *
389	 * O "≈" cobre variantes singular/plural (caixa/caixas, saco/sacos).
390	 */
391	// Containers FÍSICOS — operador conta cada um como UMA unidade do pedido,
392	// independente de quantos itens internos carregam. Bipou 1 caixa, somou +1.
393	// Bipou 1 saco, somou +1. Mesmo que a etiqueta diga qty_interna=40 dentro.
394	const CONTAINER_TYPES = new Set([
395	  'caixa', 'saco', 'balde', 'pote', 'galao', 'lata',
396	  'pacote', 'garrafa', 'tambor',
397	]);
398	
399	export function calcularIncrementoBip(
400	  _unidadePedido: string | null | undefined, // mantido pra compat — nao usado na decisao
401	  tipoEmbalagem: string | null | undefined,
402	  qtdInterna: number,
403	): number {
404	  // Normaliza alias do tipo da etiqueta
405	  const ALIASES: Record<string, string> = {
406	    cx: 'caixa', caixa: 'caixa', caixas: 'caixa',
407	    saco: 'saco', sacos: 'saco', sc: 'saco',
408	    balde: 'balde', baldes: 'balde',
409	    pote: 'pote', potes: 'pote',
410	    galao: 'galao', 'galão': 'galao', galoes: 'galao', 'galões': 'galao',
411	    lata: 'lata', latas: 'lata',
412	    pacote: 'pacote', pacotes: 'pacote', pct: 'pacote',
413	    garrafa: 'garrafa', garrafas: 'garrafa',
414	    tambor: 'tambor', tambores: 'tambor',
415	    granel: 'granel',
416	  };
417	  const t = ALIASES[(tipoEmbalagem || '').toLowerCase().trim()] ||
418	            (tipoEmbalagem || '').toLowerCase().trim();
419	
420	  // Container fechado → operador conta 1 por bip. Independente do que está dentro.
421	  // Pedido pode ser "5 caixas" ou "60 un" — quem decide é o cadastro do produto:
422	  // se ele quer pedir em caixa, define padrão tipo=caixa; se quer pedir em un,
423	  // define padrão tipo=granel ou unidade_medida='un' e a etiqueta tipo=granel.
424	  if (CONTAINER_TYPES.has(t)) return 1;
425	
426	  // Granel ou desconhecido → soma a quantidade física que tem dentro
427	  return qtdInterna || 1;
428	}
429	
430	export function isDuplicateBipError(erro: string | null | undefined): boolean {
431	  if (!erro) return false;
432	  const e = erro.toLowerCase();
433	  return e.includes("bip duplicado") || e.includes("já está com status") || e.includes("ja esta com status");
434	}
435	
436	/**
437	 * Extrai o status atual da etiqueta a partir da mensagem de erro da RPC.
438	 * Formato do erro: 'Etiqueta {uid} já está com status "{status}" — ...'
439	 */
440	function extractStatusFromError(erro: string): string | null {
441	  const m = erro.match(/status\s+"([^"]+)"/i) || erro.match(/status\s+'([^']+)'/i);
442	  return m ? m[1] : null;
443	}
444	
445	/**
446	 * Mensagem user-friendly pra erros de bip por contexto (etapa atual).
447	 *
448	 * Recebe opcionalmente o objeto etiqueta retornado pela RPC pra enriquecer
449	 * a mensagem com data + responsavel quando duplicate (operador entende que
450	 * a etiqueta foi marcada em OUTRA sessao, nao a atual).
451	 */
452	export function formatBipError(
453	  erro: string | null | undefined,
454	  etapa?: "separacao" | "conferencia" | "entrada" | "saida" | "consumo" | "descarte",
455	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
456	  etiqueta?: any | null,
457	): string {
458	  const fmtData = (iso: string | null | undefined) => {
459	    if (!iso) return "";
460	    try {
461	      const d = new Date(iso);
462	      return d.toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
463	    } catch { return ""; }
464	  };
465	  const contextoDuplicate = () => {
466	    if (!etiqueta) return "";
467	    const partes: string[] = [];
468	    if (etapa === "conferencia" && etiqueta.conferida_at) {
469	      const data = fmtData(etiqueta.conferida_at);
470	      if (data) partes.push(`em ${data}`);
471	    }
472	    if (etapa === "separacao" && etiqueta.separada_at) {
473	      const data = fmtData(etiqueta.separada_at);
474	      if (data) partes.push(`em ${data}`);
475	    }
476	    return partes.length ? ` (${partes.join(" · ")})` : "";
477	  };
478	  return formatBipErrorInner(erro, etapa, contextoDuplicate());
479	}
480	
481	function formatBipErrorInner(
482	  erro: string | null | undefined,
483	  etapa?: "separacao" | "conferencia" | "entrada" | "saida" | "consumo" | "descarte",
484	  sufixo: string = "",
485	): string {
486	  if (!erro) return "Bip rejeitado";
487	  if ((erro || "").toLowerCase().includes("descartada")) return "Etiqueta foi descartada";
488	  if (isDuplicateBipError(erro)) {
489	    const statusAtual = extractStatusFromError(erro);
