1	/**
2	 * Modal de separação digital com bip QR.
3	 *
4	 * Lê etiqueta_qr → chama RPC bipar_etiqueta(uid,'separacao',ctx) → marca
5	 * active_session_items.is_separated=true + salva qr_uid_bipado/bipado_at/bipado_por.
6	 *
7	 * Cada caixa solicitada (requested_quantity = N) gera N "slots". Bip de uma
8	 * mesma UID 2x = erro. Bip de produto fora da lista = empilha como "extra".
9	 */
10	import { useEffect, useMemo, useState } from "react";
11	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
12	import {
13	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
14	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
15	} from "@/shared/ui/alert-dialog";
16	import { Button } from "@/shared/ui/button";
17	import { ScrollArea } from "@/shared/ui/scroll-area";
18	import { Bluetooth, Camera, ScanBarcode, ArrowLeft, CheckCircle2, XCircle, Package, AlertTriangle } from "lucide-react";
19	import { toast } from "sonner";
20	import { cn } from "@/shared/lib/utils";
21	import { supabase } from "@/integrations/supabase/client";
22	import { useEtiquetaScanner, playSuccessSound, playWarningSound, playErrorSound, formatBipError, calcularIncrementoBip, type ScannedPayload } from "@/shared/hooks/useEtiquetaScanner";
23	import { CameraScannerStatus } from "./CameraScannerStatus";
24	
25	interface SessionItem {
26	  id: string;
27	  item_name: string;
28	  requested_quantity: number;
29	  is_separated: boolean;
30	  produto_master_id?: number | null;
31	  qr_uid_bipado?: string | null;
32	  /** Unidade do item (cx, kg, g, l, ml…). Default 'cx' se vazio. */
33	  unidade_medida?: string | null;
34	}
35	
36	interface BipSlot {
37	  slotId: string;
38	  itemId: string;
39	  itemName: string;
40	  produtoMasterId: number | null;
41	  slotIndex: number;
42	  totalSlots: number;
43	  status: "pending" | "confirmed" | "extra";
44	  uid?: string;
45	  payload?: ScannedPayload;
46	  bipadoAt?: number;
47	  /** Unidades dentro da caixa (preenchido ao bipar) */
48	  qtyInterna?: number;
49	  embalagem?: string | null;
50	  // Bulk = 1 slot único pro item inteiro (ex: "10 kg"). Senão = N slots discretos.
51	  isBulkUnit?: boolean;
52	  unidadeMedida?: string;
53	  bulkQty?: number;
54	}
55	
56	// Bulk = 1 etiqueta cobre a quantidade total. Inclui peso/volume contínuo
57	// E containers de volume fixo (balde, galão, tambor, barril, garrafa).
58	const BULK_UNITS = new Set([
59	  'kg', 'g', 'l', 'litro', 'litros', 'ml', 'liter', 'liters',
60	  'balde', 'baldes', 'galao', 'galão', 'galões', 'galoes',
61	  'tambor', 'tambores', 'barril', 'barris', 'garrafa', 'garrafas'
62	]);
63	const isBulkMeasure = (u: string | null | undefined) => BULK_UNITS.has((u || '').toLowerCase().trim());
64	
65	interface Props {
66	  isOpen: boolean;
67	  onClose: () => void;
68	  sessionId: string;
69	  sessionLabel: string;
70	  items: SessionItem[];
71	  lojaPreparadoraId: number | null;
72	  onItemSeparated?: (itemId: string, uid: string) => void;
73	  /** Modo padrão do scanner: fábrica usa "bluetooth", loja usa "camera". */
74	  defaultMode?: "bluetooth" | "camera";
75	}
76	
77	function buildSlots(items: SessionItem[]): BipSlot[] {
78	  const out: BipSlot[] = [];
79	  items.forEach((item) => {
80	    const unit = item.unidade_medida || 'cx';
81	    if (isBulkMeasure(unit)) {
82	      // Bulk: 1 slot único representa o pedido inteiro (ex: "10 kg" = 1 bip)
83	      const bulkQty = Number(item.requested_quantity) || 1;
84	      out.push({
85	        slotId: `${item.id}-bulk`,
86	        itemId: item.id,
87	        itemName: item.item_name,
88	        produtoMasterId: item.produto_master_id ?? null,
89	        slotIndex: 1,
90	        totalSlots: 1,
91	        status: item.is_separated ? "confirmed" : "pending",
92	        uid: item.qr_uid_bipado || undefined,
93	        isBulkUnit: true,
94	        unidadeMedida: unit,
95	        bulkQty,
96	      });
97	      return;
98	    }
99	    // Box: N slots discretos (1 etiqueta por caixa/unidade)
100	    const total = Math.max(1, Math.round(item.requested_quantity || 1));
101	    for (let i = 1; i <= total; i++) {
102	      out.push({
103	        slotId: `${item.id}-slot-${i}`,
104	        itemId: item.id,
105	        itemName: item.item_name,
106	        produtoMasterId: item.produto_master_id ?? null,
107	        slotIndex: i,
108	        totalSlots: total,
109	        status: item.is_separated && i === 1 ? "confirmed" : "pending",
110	        uid: item.qr_uid_bipado || undefined,
111	        unidadeMedida: unit,
112	      });
113	    }
114	  });
115	  return out;
116	}
117	
118	export function SeparacaoBipModal({
119	  isOpen,
120	  onClose,
121	  sessionId,
122	  sessionLabel,
123	  items,
124	  lojaPreparadoraId,
125	  onItemSeparated,
126	  defaultMode = "bluetooth",
127	}: Props) {
128	  const [slots, setSlots] = useState<BipSlot[]>([]);
129	  const [mobileTab, setMobileTab] = useState<"pending" | "confirmed" | "extras">("pending");
130	  // Dialog de transferir separacao
131	  const [reseparirDialog, setReseparirDialog] = useState<{
132	    open: boolean;
133	    uid: string;
134	    produto: string;
135	    separada_at: string | null;
136	    payload: ScannedPayload | null;
137	  }>({ open: false, uid: "", produto: "", separada_at: null, payload: null });
138	
139	  useEffect(() => {
140	    if (!isOpen) return;
141	    setSlots(buildSlots(items));
142	  }, [isOpen, items]);
143	
144	  const handleBip = async (payload: ScannedPayload) => {
145	    if (!payload.uid) {
146	      playErrorSound();
147	      toast.error("Etiqueta sem UID — não rastreável");
148	      return;
149	    }
150	
151	    if (slots.some((s) => s.uid === payload.uid && s.status !== "pending")) {
152	      playErrorSound();
153	      toast.error("Caixa já bipada nesta separação");
154	      return;
155	    }
156	
157	    // Chama RPC — fonte única de verdade
158	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
159	    const { data: rpc, error } = await (supabase.rpc as any)("bipar_etiqueta", {
160	      p_uid: payload.uid,
161	      p_etapa: "separacao",
162	      p_contexto: {
163	        loja_id: lojaPreparadoraId,
164	        referencia_tipo: "active_session",
165	        referencia_id: sessionId,
166	        payload,
167	      },
168	    });
169	    if (error) {
170	      playErrorSound();
171	      toast.error(`Falha no bip: ${error.message}`);
172	      return;
173	    }
174	    const result = rpc as { ok: boolean; erro?: string; etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; separada_at?: string | null }; alertas?: string[] };
175	    if (!result?.ok) {
176	      // Caso especial: ja separada → dialog pra transferir
177	      const erroLower = (result?.erro || "").toLowerCase();
178	      const isJaSeparada = erroLower.includes('"separada"') || erroLower.includes("separada");
179	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
180	      const etSep = result?.etiqueta as any;
181	      if (isJaSeparada && etSep?.separada_at) {
182	        playWarningSound();
183	        setReseparirDialog({
184	          open: true,
185	          uid: payload.uid,
186	          produto: etSep.produto_nome_snapshot || "produto",
187	          separada_at: etSep.separada_at,
188	          payload,
189	        });
190	        return;
191	      }
192	      playErrorSound();
193	      toast.error(formatBipError(result?.erro, "separacao", result?.etiqueta));
194	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
195	      return;
196	    }
197	    (result.alertas ?? []).forEach((a) => toast.warning(a));
198	
199	    const scannedPid = result.etiqueta?.produto_master_id ?? Number(payload.pid);
200	    const scannedName = result.etiqueta?.produto_nome_snapshot ?? "";

200	    const scannedName = result.etiqueta?.produto_nome_snapshot ?? "";
201	    const scannedQty = Number(result.etiqueta?.quantidade_interna ?? payload.qty ?? 1);
202	    const scannedEmb = result.etiqueta?.embalagem_nome ?? null;
203	    const scannedTipo = result.etiqueta?.tipo_embalagem ?? payload.tipo ?? null;
204	
205	    // Achar slot pendente correspondente
206	    const targetIdx = slots.findIndex((s) => s.status === "pending" && s.produtoMasterId === scannedPid);
207	
208	    // Quantos slots este bip cobre? Pedido bate com tipo da etiqueta → 1.
209	    // Senão → qty_interna (operador bipa 1 etiqueta, marca N slots de uma vez).
210	    const slotsCobertos = targetIdx >= 0
211	      ? calcularIncrementoBip(slots[targetIdx].unidadeMedida, scannedTipo, scannedQty)
212	      : 1;
213	
214	    if (targetIdx < 0) {
215	      // Empilha extra silenciosamente — operador ve no painel "Fora da Lista"
216	      if (navigator.vibrate) navigator.vibrate([50]);
217	      setSlots((prev) => [
218	        ...prev,
219	        {
220	          slotId: `extra-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
221	          itemId: "",
222	          itemName: scannedName || `Produto #${scannedPid}`,
223	          produtoMasterId: scannedPid,
224	          slotIndex: 1,
225	          totalSlots: 1,
226	          status: "extra",
227	          uid: payload.uid,
228	          payload,
229	          bipadoAt: Date.now(),
230	          qtyInterna: scannedQty,
231	          embalagem: scannedEmb,
232	        },
233	      ]);
234	      return;
235	    }
236	
237	    const slot = slots[targetIdx];
238	
239	    // Persiste no item da sessão
240	    const { data: { user } } = await supabase.auth.getUser();
241	    const { error: upErr } = await supabase
242	      .from("active_session_items")
243	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
244	      .update({
245	        is_separated: true,
246	        separated_by: user?.user_metadata?.nome || user?.email || "",
247	        qr_uid_bipado: payload.uid,
248	        bipado_at: new Date().toISOString(),
249	        bipado_por: user?.id ?? null,
250	      } as any)
251	      .eq("id", slot.itemId);
252	
253	    if (upErr) {
254	      playErrorSound();
255	      toast.error(`Erro ao salvar separação: ${upErr.message}`);
256	      return;
257	    }
258	
259	    playSuccessSound();
260	    if (navigator.vibrate) navigator.vibrate(100);
261	    toast.success(`Separado: ${slot.itemName}`);
262	
263	    // Marca N slots pendentes deste item de uma vez (N = slotsCobertos).
264	    // Caso pedido = un (60) + etiqueta = caixa qty 12 → 1 bip marca 12 slots.
265	    // Caso pedido = caixa (5) + etiqueta = caixa qty 12 → 1 bip marca 1 slot.
266	    setSlots((prev) => {
267	      const next = [...prev];
268	      let marcados = 0;
269	      for (let i = 0; i < next.length && marcados < slotsCobertos; i++) {
270	        if (next[i].status === "pending" && next[i].produtoMasterId === scannedPid) {
271	          next[i] = {
272	            ...next[i],
273	            status: "confirmed",
274	            // Só o primeiro slot do bip carrega o UID — os outros são "preenchidos
275	            // automaticamente" pela cobertura. Sem isso, o check de "uid já bipada"
276	            // disparava porque N slots ficavam com mesmo UID.
277	            uid: marcados === 0 ? payload.uid : undefined,
278	            payload: marcados === 0 ? payload : undefined,
279	            bipadoAt: Date.now(),
280	            qtyInterna: scannedQty,
281	            embalagem: scannedEmb,
282	          };
283	          marcados++;
284	        }
285	      }
286	      return next;
287	    });
288	
289	    onItemSeparated?.(slot.itemId, payload.uid);
290	  };
291	
292	  const scanner = useEtiquetaScanner({
293	    enabled: isOpen,
294	    onScan: handleBip,
295	    cameraElementId: "separacao-qr-reader",
296	    onInvalid: () => toast.error("QR ilegível"),
297	    onDuplicate: () => {
298	      playErrorSound();
299	      toast.error("Esta etiqueta já foi bipada");
300	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
301	    },
302	    initialMode: defaultMode,
303	  });
304	
305	  const stats = useMemo(() => {
306	    const pending = slots.filter((s) => s.status === "pending");
307	    const confirmed = slots.filter((s) => s.status === "confirmed");
308	    const extras = slots.filter((s) => s.status === "extra");
309	    const total = slots.filter((s) => s.status !== "extra").length;
310	    const unConfirmadas = confirmed.reduce((acc, s) => acc + (s.qtyInterna || 0), 0);
311	    const unExtras = extras.reduce((acc, s) => acc + (s.qtyInterna || 0), 0);
312	    return {
313	      pending,
314	      confirmed,
315	      extras,
316	      unConfirmadas,
317	      unExtras,
318	      progress: total > 0 ? Math.round((confirmed.length / total) * 100) : 0,
319	    };
320	  }, [slots]);
321	
322	  const isComplete = stats.pending.length === 0 && stats.confirmed.length > 0;
323	
324	  // Transfere separacao da req anterior pra esta — sobrescreve separada_at/por
325	  const confirmarReseparar = async () => {
326	    if (!reseparirDialog.uid || !reseparirDialog.payload) {
327	      setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null });
328	      return;
329	    }
330	    const payload = reseparirDialog.payload;
331	    try {
332	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
333	      const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta_reseparar", {
334	        p_uid: reseparirDialog.uid,
335	        p_contexto: {
336	          loja_id: lojaPreparadoraId,
337	          referencia_tipo: "active_session",
338	          referencia_id: sessionId,
339	          payload,
340	        },
341	      });
342	      const rpc = rpcRaw as { ok: boolean; erro?: string; etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null } } | null;
343	      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
344	        toast.error(rpc?.erro || rpcErr?.message || "Falha ao transferir separação");
345	        playErrorSound();
346	        return;
347	      }
348	
349	      // Aplica visualmente — marca slots como confirmed igual ao fluxo normal
350	      const scannedPid = rpc.etiqueta.produto_master_id;
351	      const scannedQty = Number(rpc.etiqueta.quantidade_interna ?? payload.qty ?? 1);
352	      const scannedEmb = rpc.etiqueta.embalagem_nome ?? null;
353	      const scannedTipo = rpc.etiqueta.tipo_embalagem ?? payload.tipo ?? null;
354	
355	      const targetIdx = slots.findIndex((s) => s.status === "pending" && s.produtoMasterId === scannedPid);
356	      if (targetIdx < 0) {
357	        toast.warning(`Transferida mas produto não está na lista — registrado como extra`);
358	        setSlots((prev) => [...prev, {
359	          slotId: `extra-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
360	          itemId: "", itemName: rpc.etiqueta!.produto_nome_snapshot || `Produto #${scannedPid}`,
361	          produtoMasterId: scannedPid, slotIndex: 1, totalSlots: 1, status: "extra",
362	          uid: payload.uid, payload, bipadoAt: Date.now(),
363	          qtyInterna: scannedQty, embalagem: scannedEmb,
364	        }]);
365	        return;
366	      }
367	      const slotsCobertos = calcularIncrementoBip(slots[targetIdx].unidadeMedida, scannedTipo, scannedQty);
368	      const slot = slots[targetIdx];
369	      const { data: { user } } = await supabase.auth.getUser();
370	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
371	      await supabase.from("active_session_items").update({
372	        is_separated: true,
373	        separated_by: user?.user_metadata?.nome || user?.email || "",
374	        qr_uid_bipado: payload.uid,
375	        bipado_at: new Date().toISOString(),
376	        bipado_por: user?.id ?? null,
377	      } as any).eq("id", slot.itemId);
378	
379	      setSlots((prev) => {
380	        const next = [...prev];
381	        let marcados = 0;
382	        for (let i = 0; i < next.length && marcados < slotsCobertos; i++) {
