389	            };
390	            marcados++;
391	          }
392	        }
393	        return next;
394	      });
395	      playSuccessSound();
396	      if (navigator.vibrate) navigator.vibrate(100);
397	      toast.success(`Separação transferida: ${slot.itemName}`);
398	      onItemSeparated?.(slot.itemId, payload.uid);
399	    } catch (e) {
400	      toast.error(`Erro: ${(e as Error).message}`);
401	      playErrorSound();
402	    } finally {
403	      setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null });
404	    }
405	  };
406	
