1	-- ===========================================================================
2	-- RPCs para TRANSFERIR conferencia/separacao entre requisicoes.
3	--
4	-- Cenario real: etiqueta foi conferida na req 683, depois bipada de novo
5	-- na req 682. Operador quer "mover" a conferencia pra req nova (corrige
6	-- erro de qual requisicao a etiqueta deveria estar).
7	--
8	-- Comportamento: sobrescreve conferida_at/separada_at + por com NOW()
9	-- e o operador atual. Mantem flag TRUE (continua conferida/separada),
10	-- mas o evento timeline registra a transferencia.
11	-- ===========================================================================
12	
13	CREATE OR REPLACE FUNCTION public.bipar_etiqueta_reconferir(
14	  p_uid       text,
15	  p_contexto  jsonb DEFAULT '{}'::jsonb
16	)
17	RETURNS jsonb
18	LANGUAGE plpgsql
19	SECURITY DEFINER
20	SET search_path = public
21	AS $func$
22	DECLARE
23	  v_etiqueta            public.etiquetas_qr%ROWTYPE;
24	  v_user_id             uuid := auth.uid();
25	  v_user_nome           text;
26	  v_loja_id             integer;
27	  v_referencia_tipo     text;
28	  v_referencia_id       text;
29	  v_conferida_anterior  timestamptz;
30	  v_conferida_por_ant   uuid;
31	BEGIN
32	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;
33	  IF NOT FOUND THEN
34	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada');
35	  END IF;
36	  IF v_etiqueta.status = 'descartada' THEN
37	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
38	  END IF;
39	
40	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
41	  v_referencia_tipo := p_contexto->>'referencia_tipo';
42	  v_referencia_id   := p_contexto->>'referencia_id';
43	  v_conferida_anterior := v_etiqueta.conferida_at;
44	  v_conferida_por_ant  := v_etiqueta.conferida_por;
45	
46	  UPDATE public.etiquetas_qr SET
47	    foi_conferida = TRUE,
48	    conferida_at  = NOW(),
49	    conferida_por = v_user_id,
50	    loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
51	  WHERE uid = p_uid
52	  RETURNING * INTO v_etiqueta;
53	
54	  SELECT COALESCE(raw_user_meta_data->>'nome', email)
55	    INTO v_user_nome FROM auth.users WHERE id = v_user_id;
56	
57	  INSERT INTO public.etiquetas_qr_eventos (
58	    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
59	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
60	  ) VALUES (
61	    p_uid, 'reconferida', 'conferencia', v_etiqueta.status, v_etiqueta.status,
62	    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
63	    jsonb_build_object(
64	      'conferida_anterior_at', v_conferida_anterior,
65	      'conferida_anterior_por', v_conferida_por_ant
66	    )
67	  );
68	
69	  RETURN jsonb_build_object(
70	    'ok', true,
71	    'etiqueta', to_jsonb(v_etiqueta),
72	    'transferida_de', v_conferida_anterior
73	  );
74	END;
75	$func$;
