78	  p_uid       text,
79	  p_contexto  jsonb DEFAULT '{}'::jsonb
80	)
81	RETURNS jsonb
82	LANGUAGE plpgsql
83	SECURITY DEFINER
84	SET search_path = public
85	AS $func$
86	DECLARE
87	  v_etiqueta            public.etiquetas_qr%ROWTYPE;
88	  v_user_id             uuid := auth.uid();
89	  v_user_nome           text;
