92	  v_referencia_id       text;
93	  v_separada_anterior   timestamptz;
94	  v_separada_por_ant    uuid;
95	BEGIN
96	  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid FOR UPDATE;
97	  IF NOT FOUND THEN
98	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta nao encontrada');
99	  END IF;
100	  IF v_etiqueta.status = 'descartada' THEN
101	    RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta descartada', 'etiqueta', to_jsonb(v_etiqueta));
102	  END IF;
103	
104	  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
105	  v_referencia_tipo := p_contexto->>'referencia_tipo';
106	  v_referencia_id   := p_contexto->>'referencia_id';
107	  v_separada_anterior := v_etiqueta.separada_at;
108	  v_separada_por_ant  := v_etiqueta.separada_por;
109	
110	  UPDATE public.etiquetas_qr SET
111	    foi_separada = TRUE,
112	    separada_at  = NOW(),
113	    separada_por = v_user_id,
114	    loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
115	  WHERE uid = p_uid
116	  RETURNING * INTO v_etiqueta;
117	
118	  SELECT COALESCE(raw_user_meta_data->>'nome', email)
119	    INTO v_user_nome FROM auth.users WHERE id = v_user_id;
120	
121	  INSERT INTO public.etiquetas_qr_eventos (
122	    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
123	    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
124	  ) VALUES (
125	    p_uid, 'reseparada', 'separacao', v_etiqueta.status, v_etiqueta.status,
126	    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
127	    jsonb_build_object(
128	      'separada_anterior_at', v_separada_anterior,
129	      'separada_anterior_por', v_separada_por_ant
130	    )
131	  );
132	
133	  RETURN jsonb_build_object(
134	    'ok', true,
135	    'etiqueta', to_jsonb(v_etiqueta),
136	    'transferida_de', v_separada_anterior
137	  );
138	END;
139	$func$;
